    k2 = k;
    CHECK(bip32_ckd_priv(Curve::Secp256k1, k, 0 | H, k));  // in place
    CHECK_EQ_HEX(k.key, 32, "edb2e14f9ee77d26dd93b4ecede8d16ed408ce149b6cd80b0715a2d911a0afea");
    CHECK_EQ_HEX(k.chain, 32, "47fdacbd0f1097043b78c63c20c34ef4ed9a111d980047ad16282c7ae6236141");
    CHECK(bip32_ckd_priv(Curve::Secp256k1, k, 1, k));  // in place, non-hardened
    CHECK_EQ_HEX(k.key, 32, "3c6cb8d0f6a264c91ea8b5030fadaa8e538b020f0a387421a12de9319dc93368");
