// ------------------------------------------------------------------------------------------------ round trips
static void test_roundtrips() {
  CHECK_SECTION("random sign/verify/recover round trips (self-consistency)");
  for (int ci = 0; ci < 2; ci++) {
    const Curve c = curve_of(ci);
    int fails = 0, highs = 0, recid1 = 0;
    const int N = 150;
    for (int it = 0; it < N; it++) {
      uint8_t priv[32], dg[32], pub[64], rs[64], rec[64];
      rnd(priv, 32);
      if (it % 10 == 0) std::memset(priv, 0, 28);  // small keys too
      rnd(dg, 32);
      if (!ec_pubkey(c, priv, pub)) continue;  // (out of range: astronomically unlikely)
      int rid = -1;
      bool ok = ecdsa_sign(c, priv, dg, rs, &rid);
      ok = ok && (rid == 0 || rid == 1);
      ok = ok && ecdsa_verify(c, pub, dg, rs);
      ok = ok && ecdsa_recover(c, dg, rs, rid, rec) && std::memcmp(rec, pub, 64) == 0;
      if (!is_low_s(c, rs)) highs++;
      recid1 += rid;
      dg[0] ^= 0x80;
      ok = ok && !ecdsa_verify(c, pub, dg, rs);
      if (!ok) fails++;
    }
    CHECK_EQ(fails, 0);
    CHECK_EQ(highs, 0);
    CHECK(recid1 > N / 5 && recid1 < N * 4 / 5);  // both recids occur
  }
}

static void bench() {
  CHECK_SECTION("host timing (informational)");
  Bytes seed = HX(DEMO_SEED);
  uint8_t priv[32], pub[64], dg[32], rs[64];
  sha256(S("bench"), 5, dg);
  for (int ci = 0; ci < 2; ci++) {
    const Curve c = curve_of(ci);
    CHECK(derive_path(c, seed.data(), seed.size(), ci ? PATH_P1 : PATH_K1, ci ? 2 : 5, priv));
    CHECK(ec_pubkey(c, priv, pub));
    const int N = 50;
    int rid = 0;
    std::clock_t t0 = std::clock();
    for (int i = 0; i < N; i++) {
      dg[0] = uint8_t(i);
      ecdsa_sign(c, priv, dg, rs, &rid);
    }
    std::clock_t t1 = std::clock();
    for (int i = 0; i < N; i++) ecdsa_recover(c, dg, rs, rid, pub);
    std::clock_t t2 = std::clock();
    for (int i = 0; i < N; i++) derive_path(c, seed.data(), seed.size(), ci ? PATH_P1 : PATH_K1, ci ? 2 : 5, priv);
    std::clock_t t3 = std::clock();
    const double ms = 1000.0 / CLOCKS_PER_SEC / N;
    std::printf("   %s: sign %.2f ms, recover %.2f ms, derive_path %.2f ms (host)\n", ci ? "P-256" : "secp256k1",
                double(t1 - t0) * ms, double(t2 - t1) * ms, double(t3 - t2) * ms);
  }
}

